1	/**
2	 * Guards the canonical branch-name regex against drift between its two encodings:
3	 * the `regex` input of the contributing-check CI action and the executable pattern
4	 * in the shared pr-title-grammar.md block that branch-create and preflight-check
5	 * validate against before a branch is created or committed on.
6	 *
7	 * The CI action is the enforcement of last resort — it fires only once a PR is
8	 * open, when a bad head branch can no longer be renamed and the PR must be
9	 * re-created. The grammar block is what the skills check before the branch ever
10	 * exists. If either encoding is edited alone, agents validate one shape and CI
11	 * another, reintroducing exactly the late failure the early gates exist to
12	 * prevent; this test makes such an edit fail in CI instead.
13	 *
14	 * Vacuous-pass defence: the extracted regex must be non-empty and above a minimum
15	 * length, so a reworded `regex:` line cannot extract "" and trivially match.
16	 */
17	import { readFile } from "node:fs/promises";
18	import { join } from "node:path";
19	
20	import { describe, expect, test } from "bun:test";
21	
22	const actionDir = join(import.meta.dirname, "..");
23	const repoRoot = join(actionDir, "..", "..", "..");
24	const contributingCheckPath = join(
25	  repoRoot,
26	  ".github/actions/contributing-check/action.yml",
27	);
28	const grammarPath = join(
29	  repoRoot,
30	  "claude-plugins/autopilot/skills/shared-rules/references/pr-title-grammar.md",
31	);
32	
33	/** Shortest the real pattern can be; anything smaller means the extraction went wrong. */
34	const minRegexLength = 80;
35	
36	/** The single-quoted value of the action's `regex:` input line; null when absent. */
37	function extractCiRegex(actionYml: string): string | null {
38	  return /^\s*regex:\s*'(.+)'\s*$/m.exec(actionYml)?.[1] ?? null;
39	}
40	
41	describe("branch grammar sync", () => {
42	  test("pr-title-grammar.md carries the contributing-check regex verbatim", async () => {
43	    const [actionYml, grammar] = await Promise.all([
44	      readFile(contributingCheckPath, "utf8"),
45	      readFile(grammarPath, "utf8"),
46	    ]);
47	    const ciRegex = extractCiRegex(actionYml);
48	    expect(ciRegex).not.toBeNull();
49	    expect(ciRegex!.length).toBeGreaterThan(minRegexLength);
50	    // On its own line means inside the fenced canonical-regex block, not in prose.
51	    expect(grammar).toContain(`\n${ciRegex!}\n`);
52	  });
53	});
