1	/**
2	 * Guards the shared instruction blocks that live in
3	 * claude-plugins/autopilot/skills/shared-rules/references/. Each block is the single
4	 * source of truth for text several skills or agents need; consumers read the block at
5	 * runtime instead of carrying a copy (see sharedRulesInvocation.test.ts for that half).
6	 *
7	 * Two runtimes can read nothing at all, so they keep a literal inlined copy:
8	 * releaseNotesPrompt.ts is passed to the Anthropic API as a raw system prompt with no
9	 * tools, and the structured-output agents declare restrictive `tools` lists (expert-review
10	 * declares `tools: []`). Those copies are still single-sourced — this test asserts each is
11	 * byte-identical to its canonical block.
12	 *
13	 * Replaces referenceFormattingSync.test.ts, which guarded only the reference-formatting
14	 * block across ~25 inlined copies. RFC-0001 remains canonical for that one block: the
15	 * reference file is asserted equal to the RFC's own sentinel block, so the RFC cannot
16	 * silently degrade into a third mutable copy.
17	 *
18	 * Vacuous-pass defences, both deliberate: every extracted block must be non-empty and
19	 * above a minimum length (a missing sentinel would otherwise extract "" and compare
20	 * equal to another ""), and the retained-copy matrix is explicit test data rather than a
21	 * glob, so a dropped or newly added inlined copy fails loudly instead of shrinking the
22	 * matrix in silence.
23	 */
24	import { readdir, readFile } from "node:fs/promises";
25	import { basename, join } from "node:path";
26	
27	import { describe, expect, test } from "bun:test";
28	
29	const actionDir = join(import.meta.dirname, "..");
30	const repoRoot = join(actionDir, "..", "..", "..");
31	const referencesDir = join(
32	  repoRoot,
33	  "claude-plugins/autopilot/skills/shared-rules/references",
34	);
35	const rfcPath = join(repoRoot, "rfc/0001-reference-formatting.md");
36	const agentsDir = join(repoRoot, "claude-plugins/autopilot/agents");
37	const releasePrompt = join(
38	  repoRoot,
39	  ".github/actions/release-action/src/releaseNotesPrompt.ts",
40	);
41	
42	/** Shortest a real block can be; anything smaller means the extraction went wrong. */
43	const minBlockLength = 80;
44	
45	/** Reference file → the sentinel name delimiting its canonical block. */
46	const blockSentinels: Record<string, string> = {
47	  "reference-formatting.md": "ref-format",
48	  "askuserquestion-format.md": "auq-format",
49	  "askuserquestion-contract.md": "auq-contract",
50	  "repomix-snapshot.md": "repomix-snapshot",
51	  "agent-json-output.md": "agent-json",
52	  "issue-body-grammar.md": "issue-body-grammar",
53	  "linear-mcp-access.md": "linear-mcp",
54	  "peer-cli-delegation.md": "peer-cli",
55	  "pr-title-grammar.md": "pr-title-grammar",
56	  "pr-body-grammar.md": "pr-body-grammar",
57	};
58	
59	/**
60	 * Every place a block is still inlined because the runtime cannot read a file.
61	 * Explicit on purpose — see the vacuous-pass note in the file header.
62	 */
63	const retainedCopies: { block: string; file: string; unescapeBackticks?: boolean }[] = [
64	  // Raw Anthropic API system prompt: no Claude Code SDK, therefore no tools at all.
65	  { block: "reference-formatting.md", file: releasePrompt, unescapeBackticks: true },
66	  // Structured-output agents: each declares its own `tools`, and expert-review declares [].
67	  ...[
68	    "analyze-pr-commits.md",
69	    "analyze-staged-changes.md",
70	    "digest-branch-diff.md",
71	    "digest-repo-standards.md",
72	    "digest-session-history.md",
73	    "expert-review.md",
74	    "fetch-pr-reviews.md",
75	    "resolve-alert-context.md",
76	    "resolve-assignees.md",
77	    "resolve-issue-context.md",
78	    "scan-and-analyze-todos.md",
79	    "search-codebase-todos.md",
80	  ].map((name) => ({ block: "agent-json-output.md", file: join(agentsDir, name) })),
81	];
82	
83	/** Extract the named sentinel-delimited block from `content`, trimmed; null when absent. */
84	function extractBlock(content: string, sentinel: string): string | null {
85	  const pattern = new RegExp(
86	    `<!-- ${sentinel}:start -->([\\s\\S]*?)<!-- ${sentinel}:end -->`,
87	  );
88	  return pattern.exec(content)?.[1].trim() ?? null;
89	}
90	
91	const canonical = new Map<string, string>();
92	for (const [file, sentinel] of Object.entries(blockSentinels)) {
93	  const block = extractBlock(await readFile(join(referencesDir, file), "utf8"), sentinel);
94	  if (block) canonical.set(file, block);
95	}
96	
97	describe("shared block canonicals", () => {
98	  test("every reference file on disk is registered", async () => {
99	    const onDisk = (await readdir(referencesDir)).filter((f) => f.endsWith(".md")).sort();
100	    expect(onDisk).toEqual(Object.keys(blockSentinels).sort());
101	  });
102	
103	  test.each(Object.keys(blockSentinels))("%s exposes a substantial block", (file) => {
104	    const block = canonical.get(file);
105	    expect(block).not.toBeNull();
106	    expect(block).toBeDefined();
107	    expect(block!.length).toBeGreaterThan(minBlockLength);
108	  });
109	
110	  test("RFC-0001 stays canonical for the reference-formatting block", async () => {
111	    const fromRfc = extractBlock(await readFile(rfcPath, "utf8"), "ref-format");
112	    expect(fromRfc).not.toBeNull();
113	    expect(fromRfc!.length).toBeGreaterThan(minBlockLength);
114	    expect(canonical.get("reference-formatting.md")).toBe(fromRfc!);
115	  });
116	});
117	
118	describe("retained inlined copies", () => {
119	  test.each(retainedCopies.map((c) => [basename(c.file), c] as const))(
120	    "%s inlines its block verbatim",
121	    async (_name, copy) => {
122	      const raw = await readFile(copy.file, "utf8");
123	      // Inside a template literal the block's backticks are escaped as \` in source.
124	      const source = copy.unescapeBackticks ? raw.replaceAll("\\`", "`") : raw;
125	      const sentinel = blockSentinels[copy.block];
126	      const inlined = extractBlock(source, sentinel);
127	      expect(inlined).not.toBeNull();
128	      expect(inlined).toBe(canonical.get(copy.block)!);
129	    },
130	  );
131	
132	  test("no agent carries the JSON block without being registered", async () => {
133	    const registered = new Set(
134	      retainedCopies.filter((c) => c.block === "agent-json-output.md").map((c) => basename(c.file)),
135	    );
136	    const carrying: string[] = [];
137	    for (const name of await readdir(agentsDir)) {
138	      if (!name.endsWith(".md")) continue;
139	      const raw = await readFile(join(agentsDir, name), "utf8");
140	      if (raw.includes("Output ONLY a single JSON object")) carrying.push(name);
141	    }
142	    expect(carrying.sort()).toEqual([...registered].sort());
143	  });
144	});
