1	/**
2	 * Guards the single canonical pr-review SKILL.md URL that the review and answer
3	 * skills build every `CHECK-*` rule link from. The URL is single-sourced to the
4	 * action's `rules_doc_url` input default: the skills receive it at runtime via
5	 * `RULES_DOC_URL` and no longer hardcode a copy. So this asserts the action default
6	 * still points at the pr-review SKILL.md (a typo there would break every rule link
7	 * in a review) and that both skills keep documenting the action input as the one
8	 * canonical copy, rather than reintroducing a drift-prone duplicate.
9	 */
10	import { readFile, readdir } from "node:fs/promises";
11	import { join } from "node:path";
12	
13	import { describe, expect, test } from "bun:test";
14	
15	const actionDir = join(import.meta.dirname, "..");
16	const repoRoot = join(actionDir, "..", "..", "..");
17	const skillsDir = join(repoRoot, "claude-plugins/autopilot/skills");
18	const reviewSkill = join(skillsDir, "pr-review/SKILL.md");
19	const answerSkill = join(skillsDir, "pr-answer/SKILL.md");
20	
21	const canonicalCopyPhrase = "`rules_doc_url` input default is the one canonical copy";
22	
23	describe("rules_doc_url single source", () => {
24	  test("action default points at the canonical pr-review SKILL.md", async () => {
25	    const actionYml = await readFile(join(actionDir, "action.yml"), "utf8");
26	    const actionDefault = /rules_doc_url:[\s\S]*?default:\s*"([^"]+)"/.exec(actionYml)?.[1];
27	    expect(actionDefault).toContain("/pr-review/SKILL.md");
28	  });
29	
30	  test("review and answer skills single-source the URL from the action input", async () => {
31	    for (const skill of [reviewSkill, answerSkill]) {
32	      const content = await readFile(skill, "utf8");
33	      expect(content).toContain(canonicalCopyPhrase);
34	    }
35	  });
36	
37	  // GitHub renders the `<a id="CHECK-…">` anchors in pr-review SKILL.md as
38	  // lowercase `user-content-…` ids and URL-fragment lookup is case-sensitive,
39	  // so a prescribed `#CHECK-…` fragment lands at the top of the file instead of
40	  // the rule (observed in wefortis/fortune-os#120). Every skill must prescribe
41	  // the fragment as the rule code lowercased (`#check-bug-002`, `#<code>`).
42	  test("no skill prescribes an uppercase rule-link fragment", async () => {
43	    const offenders: string[] = [];
44	    for (const dir of await readdir(skillsDir)) {
45	      const content = await readFile(join(skillsDir, dir, "SKILL.md"), "utf8").catch(() => "");
46	      const fragments = content.match(/#(?:check-[a-z0-9<>-]+|<code[0-9]*>)/gi) ?? [];
47	      offenders.push(...fragments.filter((f) => f !== f.toLowerCase()).map((f) => `${dir}: ${f}`));
48	    }
49	    expect(offenders).toEqual([]);
50	  });
51	});
