1	/**
2	 * Guards the runtime half of the shared-rules mechanism: every autopilot skill must
3	 * point at the shared block it needs, and must no longer carry a copy of it.
4	 *
5	 * Discovery is the load-bearing property, inherited from the referenceFormattingSync
6	 * test this replaces: the skill list comes from readdir, not a hardcoded array, so a
7	 * newly added skill cannot ship without a reference-formatting directive. Opting a skill
8	 * out requires naming it in `noRefDirective` with a reason, which is reviewable.
9	 *
10	 * What this CANNOT prove: that the model actually reads the block at runtime. CI sees
11	 * text in a file, nothing more — the same limit prBodyReferenceFormatting.test.ts states
12	 * for its own presence guard. Runtime evidence comes from the dry-run recorded on the PR.
13	 *
14	 * Directives are written as markdown links, so linkResolution.test.ts independently
15	 * verifies each target exists; the assertion here is that the path is present and names a
16	 * real reference file, which catches a renamed block before it breaks every call site.
17	 */
18	import { readdir, readFile } from "node:fs/promises";
19	import { join } from "node:path";
20	
21	import { describe, expect, test } from "bun:test";
22	
23	const actionDir = join(import.meta.dirname, "..");
24	const repoRoot = join(actionDir, "..", "..", "..");
25	const skillsDir = join(repoRoot, "claude-plugins/autopilot/skills");
26	const referencesDir = join(skillsDir, "shared-rules/references");
27	
28	/** Skills that legitimately carry no reference-formatting directive. */
29	const noRefDirective = new Set([
30	  // Owns the canonical blocks; pointing at itself would be circular.
31	  "shared-rules",
32	]);
33	
34	/**
35	 * A distinctive phrase from each relocated block. Presence in a consumer means the
36	 * inlined copy came back — matching on a phrase rather than the whole block catches
37	 * partial leftovers too.
38	 */
39	const removedBlockPhrases: Record<string, string> = {
40	  "reference-formatting": "Backticks suppress GitHub autolinking",
41	  "askuserquestion-format": "renders as raw text",
42	  "askuserquestion-contract": "Copy the full preview string literally into every option",
43	  "repomix-snapshot": "fall back to `mcp__repomix__pack_codebase` with",
44	  "issue-body-grammar": "each section answers exactly one question",
45	  "linear-mcp-access": "never bind a generic tool name",
46	  "peer-cli-delegation": "zero bytes of stdout",
47	  "pr-title-grammar": "Release keyword is required, capitalized exactly as shown",
48	  "pr-body-grammar": "DO NOT use `**Release Notes:**` (capital",
49	};
50	
51	const skillDirs = (await readdir(skillsDir, { withFileTypes: true }))
52	  .filter((e) => e.isDirectory())
53	  .map((e) => e.name)
54	  .sort();
55	
56	async function readSkill(name: string): Promise<string> {
57	  return readFile(join(skillsDir, name, "SKILL.md"), "utf8");
58	}
59	
60	/** Every `../shared-rules/references/<file>.md` path a skill points at. */
61	function directiveTargets(content: string): string[] {
62	  return [...content.matchAll(/(?:\.\.\/)+shared-rules\/references\/([\w-]+\.md)/g)].map(
63	    (m) => m[1],
64	  );
65	}
66	
67	describe("shared-rules invocation", () => {
68	  test("skills are discovered, not hardcoded", () => {
69	    expect(skillDirs.length).toBeGreaterThan(20);
70	    expect(skillDirs).toContain("shared-rules");
71	  });
72	
73	  test.each(skillDirs.filter((n) => !noRefDirective.has(n)))(
74	    "%s directs the reader to the reference-formatting block",
75	    async (name) => {
76	      expect(await readSkill(name)).toContain(
77	        "shared-rules/references/reference-formatting.md",
78	      );
79	    },
80	  );
81	
82	  test.each(skillDirs)("%s only points at reference files that exist", async (name) => {
83	    const available = new Set(await readdir(referencesDir));
84	    for (const target of directiveTargets(await readSkill(name))) {
85	      expect(available).toContain(target);
86	    }
87	  });
88	
89	  test.each(skillDirs.filter((n) => n !== "shared-rules"))(
90	    "%s carries no re-inlined block text",
91	    async (name) => {
92	      const content = await readSkill(name);
93	      for (const [block, phrase] of Object.entries(removedBlockPhrases)) {
94	        expect(`${name}:${block}:${content.includes(phrase)}`).toBe(
95	          `${name}:${block}:false`,
96	        );
97	      }
98	    },
99	  );
100	});
